import numpy as np

def lenta(x):
    tot = 0.0
    for v in x:
        if v > 0:
            tot += (v * v + 1) ** 0.5
    return tot

def veloce(x):
    p = x[x > 0]
    return np.sqrt(p**2 + 1).sum()

x = np.random.default_rng(0).normal(size=10_000)
print(lenta(x), veloce(x))
